-- CFDNS Manager by Lord Eagle unified MySQL schema.
-- Runtime startup also applies these CREATE TABLE IF NOT EXISTS statements so a fresh managed database is ready.
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, open_id VARCHAR(191) NOT NULL UNIQUE, email VARCHAR(255), name VARCHAR(255), role VARCHAR(32) NOT NULL DEFAULT 'user', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token_hash VARCHAR(128) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS servers (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT, name VARCHAR(191) NOT NULL, host VARCHAR(255) NOT NULL, port INT NOT NULL DEFAULT 22, username VARCHAR(191) NOT NULL, auth_type VARCHAR(32) NOT NULL DEFAULT 'password', password TEXT, private_key TEXT, passphrase TEXT, status VARCHAR(32) NOT NULL DEFAULT 'unknown', notes TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cloudflare_connections (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, name VARCHAR(191) NOT NULL, api_token TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dns_zones (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, connection_id INT NOT NULL, zone_id VARCHAR(191) NOT NULL, zone_name VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS site_links (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, server_id INT NOT NULL, zone_id INT NOT NULL, hostname VARCHAR(255) NOT NULL, port INT NOT NULL, proxied BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, owner_id INT NOT NULL, action VARCHAR(128) NOT NULL, target_type VARCHAR(64) NOT NULL, target_id VARCHAR(191), status VARCHAR(32) NOT NULL, metadata TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
